// ============================================================================
// Root Store
// ============================================================================

export class RootStore {
  user: UserStore
  machine: MachineStore
  filmCode: FilmCodeStore
  downtimeReason: DowntimeReasonStore
  productionEntry: ProductionEntryStore
  target: TargetStore
  exportQuantity: ExportQuantityStore
  packingCost: PackingCostStore
  customer: CustomerStore
  dispatch: DispatchStore
  auditLog: AuditLogStore
  userPermission: UserPermissionStore
  userPlant: UserPlantStore

  constructor() {
    this.user = new UserStore()
    this.machine = new MachineStore()
    this.filmCode = new FilmCodeStore()
    this.downtimeReason = new DowntimeReasonStore()
    this.productionEntry = new ProductionEntryStore()
    this.target = new TargetStore()
    this.exportQuantity = new ExportQuantityStore()
    this.packingCost = new PackingCostStore()
    this.customer = new CustomerStore()
    this.dispatch = new DispatchStore()
    this.auditLog = new AuditLogStore()
    this.userPermission = new UserPermissionStore()
    this.userPlant = new UserPlantStore()
    makeAutoObservable(this)
  }

  /** Clear all stores */
  clearAll() {
    this.user.clear()
    this.machine.clear()
    this.filmCode.clear()
    this.downtimeReason.clear()
    this.productionEntry.clear()
    this.target.clear()
    this.exportQuantity.clear()
    this.packingCost.clear()
    this.customer.clear()
    this.dispatch.clear()
    this.auditLog.clear()
    this.userPermission.clear()
    this.userPlant.clear()
  }
}

// ============================================================================
// Factory & Singleton
// ============================================================================

let rootStore: RootStore | null = null

/**
 * Get or create the root store singleton
 */
export function getStore(): RootStore {
  if (!rootStore) {
    rootStore = new RootStore()
  }
  return rootStore
}

/**
 * Create a new root store (for testing or SSR)
 */
export function createStore(): RootStore {
  return new RootStore()
}

/**
 * Reset the singleton store
 */
export function resetStore(): void {
  rootStore = null
}
